def norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,c0=min(rs),min(cs)
    s=np.zeros((max(rs)-r0+1,max(cs)-c0+1),int)
    for r,c in cells: s[r-r0,c-c0]=1
    return s
